import { ChangeEvent, FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { BadgeDollarSign, BookOpenCheck, Cable, Clock3, Mail, Settings2, Tags, UsersRound, Wrench } from 'lucide-react';
import type { Actor } from './App';
import { request } from './App';
import { ConfirmDialog } from './ui';
import { OwnerCommercialDashboard } from './OwnerCommercialDashboard';
import { ContextualHelpTrigger } from './ContextualHelp';

type Member = { id: string; user_id: string; email: string; username?: string; display_name: string; status: 'active' | 'inactive'; roles: string[] };
type CatalogItem = { id: string; code: string; name: string };
type Team = { id: string; name: string; is_active: boolean; members: { user_id: string; display_name: string }[] };
type Rule = { id: string; department_id: string | null; assignee_user_id: string; is_active: boolean };
type AdministrationKey = 'members' | 'directory' | 'catalog' | 'vocabulary' | 'teams' | 'automation' | 'settings' | 'extensions' | 'commercial';
type AdministrationItem = { key: AdministrationKey; label: string; path: string; icon: typeof UsersRound; ownerOnly?: boolean };

const roles = [
  ['REQUESTER', 'درخواست‌کننده'], ['EXPERT', 'کارشناس'], ['SUPERVISOR', 'سرپرست'], ['ORG_ADMIN', 'مدیر سازمان'],
] as const;
const catalogs = [
  ['departments', 'واحدها'], ['categories', 'دسته‌بندی‌ها'], ['locations', 'مکان‌ها'], ['disciplines', 'رشته‌ها'],
] as const;

const administrationGroups: { label: string; items: AdministrationItem[] }[] = [
  { label: 'کاربران', items: [{ key: 'members', label: 'کاربران و نقش‌ها', path: '/admin/members', icon: UsersRound }, { key: 'directory', label: 'اتصال دایرکتوری', path: '/admin/directory', icon: Cable }] },
  { label: 'خدمات و ساختار', items: [
    { key: 'catalog', label: 'کاتالوگ خدمات', path: '/admin/catalog', icon: BookOpenCheck },
    { key: 'vocabulary', label: 'عنوان‌ها و برچسب‌ها', path: '/admin/vocabulary', icon: Tags },
    { key: 'teams', label: 'تیم‌ها', path: '/admin/teams', icon: Wrench },
  ] },
  { label: 'عملیات', items: [{ key: 'automation', label: 'SLA و تخصیص', path: '/admin/automation', icon: Clock3 }] },
  { label: 'تنظیمات', items: [
    { key: 'settings', label: 'درخواست و ظاهر سازمان', path: '/admin/settings', icon: Settings2 },
    { key: 'extensions', label: 'فیلدهای سفارشی و ایمیل', path: '/admin/extensions', icon: Mail },
  ] },
  { label: 'تجاری', items: [{ key: 'commercial', label: 'سهمیه و پشتیبانی', path: '/admin/commercial', icon: BadgeDollarSign, ownerOnly: true }] },
] ;

export function OrganizationAdminConsole({ actor }: { actor: Actor }) {
  const location = useLocation();
  const navigate = useNavigate();
  const [notice, setNotice] = useState('');
  const visibleGroups = administrationGroups.map((group) => ({ ...group, items: group.items.filter((item) => !item.ownerOnly || actor.membership.role_codes.includes('ORG_OWNER')) })).filter((group) => group.items.length);
  const visibleItems = visibleGroups.flatMap((group) => group.items);
  const activeItem = visibleItems.find((item) => item.path === location.pathname) ?? visibleItems[0];
  const tab = activeItem.key as AdministrationKey;

  useEffect(() => {
    if (location.pathname !== activeItem.path) navigate(activeItem.path, { replace: true });
  }, [activeItem.path, location.pathname, navigate]);

  return <section className="page admin-console">
    <div className="page-intro admin-workspace-intro"><div><p className="eyebrow">مدیریت سازمان</p><h2>{activeItem.label}</h2><p>تنظیمات و عملیات سازمان را در بخش مرتبط مدیریت کنید.</p></div></div>
    <div className="admin-mobile-selector">
      <label>بخش مدیریت سازمان
        <select value={activeItem.path} onChange={(event) => { setNotice(''); navigate(event.target.value); }}>
          {visibleGroups.map((group) => <optgroup key={group.label} label={group.label}>{group.items.map((item) => <option key={item.key} value={item.path}>{item.label}</option>)}</optgroup>)}
        </select>
      </label>
    </div>
    <div className="admin-workspace">
      <nav className="admin-section-nav" aria-label="بخش‌های مدیریت سازمان">
        {visibleGroups.map((group) => <section key={group.label}><p>{group.label}</p>{group.items.map((item) => { const Icon = item.icon; return <NavLink key={item.key} to={item.path} onClick={() => setNotice('')}><Icon size={17} aria-hidden="true"/><span>{item.label}</span></NavLink>; })}</section>)}
      </nav>
      <div className="admin-workspace-content">
        {notice && <p className="notice" role="status">{notice}</p>}
        {tab === 'directory' && <ContextualHelpTrigger actor={actor} relatedFeature="DIRECTORY_CONNECTOR" label="راهنمای اتصال دایرکتوری"/>}
        {tab === 'members' && <ContextualHelpTrigger actor={actor} relatedFeature="ORGANIZATION_MEMBERSHIP" label="راهنمای کاربران و CSV"/>}
        {['catalog','vocabulary','teams','settings','extensions'].includes(tab) && <ContextualHelpTrigger actor={actor} relatedFeature="TICKET_CONFIGURATION" label="راهنمای تنظیمات تیکت"/>}
        {tab === 'automation' && <ContextualHelpTrigger actor={actor} relatedFeature="SLA_ADMINISTRATION" label="راهنمای SLA و تقویم کاری"/>}
        {tab === 'commercial' && <ContextualHelpTrigger actor={actor} relatedFeature="COMMERCIAL_DASHBOARD" label="راهنمای سهمیه و پشتیبانی"/>}
        {tab === 'members' && <><MembersPanel actor={actor} onNotice={setNotice}/><CsvMemberImport actor={actor} onNotice={setNotice}/></>}
        {tab === 'directory' && <><DirectoryConnectorControlPanel actor={actor} onNotice={setNotice}/><DirectoryOperationalPanel actor={actor}/><DirectoryPolicyControls actor={actor}/><DirectoryRunHistory actor={actor}/></>}
        {tab === 'catalog' && <CatalogPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'vocabulary' && <VocabularyPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'teams' && <TeamsPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'automation' && <AutomationPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'settings' && <SettingsPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'extensions' && <ExtensionsPanel actor={actor} onNotice={setNotice}/>}
        {tab === 'commercial' && <OwnerCommercialDashboard actor={actor}/>}
      </div>
    </div>
  </section>;
}

function VocabularyPanel({actor,onNotice}:{actor:Actor;onNotice:(message:string)=>void}) {
  const [titles,setTitles]=useState<{id:string;title:string;usage_count:number}[]>([]); const [tags,setTags]=useState<{id:string;name:string;kind:string;usage_count:number}[]>([]); const [error,setError]=useState('');
  const load=()=>Promise.all([request('/admin/title-library',actor.session,actor.organizationId),request('/admin/tag-vocabulary',actor.session,actor.organizationId)]).then(([nextTitles,nextTags])=>{setTitles(nextTitles as typeof titles);setTags(nextTags as typeof tags);}).catch(cause=>setError(cause instanceof Error?cause.message:'دریافت واژگان ناموفق بود.'));
  useEffect(()=>{void load();},[actor.organizationId]);
  const review=async(kind:'title'|'tag',id:string,decision:'ACTIVE'|'DISABLED')=>{try{await request(kind==='title'?`/admin/title-library/${id}/review`:`/admin/tag-vocabulary/${id}/review`,actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({decision})});onNotice(decision==='ACTIVE'?'مورد تأیید و فعال شد.':'مورد غیرفعال شد.');load();}catch(cause){setError(cause instanceof Error?cause.message:'ثبت تصمیم ناموفق بود.');}};
  const tagKinds:Record<string,string>={DOMAIN:'حوزه',SERVICE_ASSET:'خدمت یا تجهیز',ISSUE_TYPE:'نوع مسئله',IMPACT_SCOPE:'دامنه اثر',CONTEXT:'زمینه',OTHER:'سایر'};
  return <div className="admin-stack"><section className="card"><h3>واژگان در انتظار تأیید</h3><p className="hint">عنوان‌ها و هشتگ‌های تازه ابتدا در انتظار می‌مانند؛ فقط موارد فعال به AI پیشنهاد می‌شوند.</p>{error&&<p className="error" role="alert">{error}</p>}<div className="admin-grid"><div className="table-wrap"><h4>عنوان‌های پیشنهادی</h4><table><thead><tr><th>عنوان</th><th>استفاده</th><th>عملیات</th></tr></thead><tbody>{titles.map(item=><tr key={item.id}><td>{item.title}</td><td>{item.usage_count.toLocaleString('fa-IR')}</td><td><button type="button" onClick={()=>void review('title',item.id,'ACTIVE')}>تأیید</button><button type="button" className="secondary" onClick={()=>void review('title',item.id,'DISABLED')}>رد</button></td></tr>)}{!titles.length&&<tr><td colSpan={3}>عنوانی برای تأیید نیست.</td></tr>}</tbody></table></div><div className="table-wrap"><h4>هشتگ‌های پیشنهادی</h4><table><thead><tr><th>هشتگ</th><th>نوع</th><th>استفاده</th><th>عملیات</th></tr></thead><tbody>{tags.map(item=><tr key={item.id}><td>#{item.name}</td><td>{tagKinds[item.kind]??item.kind}</td><td>{item.usage_count.toLocaleString('fa-IR')}</td><td><button type="button" onClick={()=>void review('tag',item.id,'ACTIVE')}>تأیید</button><button type="button" className="secondary" onClick={()=>void review('tag',item.id,'DISABLED')}>رد</button></td></tr>)}{!tags.length&&<tr><td colSpan={4}>هشتگی برای تأیید نیست.</td></tr>}</tbody></table></div></div></section></div>;
}

function ExtensionsPanel({actor,onNotice}:{actor:Actor;onNotice:(message:string)=>void}) { const [fields,setFields]=useState<{id:string;field_key:string;label:string;field_type:string;options:unknown[];is_required:boolean;is_active:boolean}[]>([]);const [invalidFieldCount,setInvalidFieldCount]=useState(0);const [field,setField]=useState({fieldKey:'',label:'',fieldType:'TEXT',options:'',isRequired:false});const [email,setEmail]=useState({inboundAddress:'',senderName:'',enabled:false});const [error,setError]=useState('');const typeLabels:Record<string,string>={TEXT:'متن',NUMBER:'عدد',DATE:'تاریخ',SELECT:'انتخابی',BOOLEAN:'بله/خیر'};const load=()=>Promise.all([request('/admin/custom-fields',actor.session,actor.organizationId),request('/admin/email-integration',actor.session,actor.organizationId)]).then(([nextFields,nextEmail])=>{const safe=(nextFields as typeof fields).filter(item=>!item.label.includes('?')&&!item.label.includes('\uFFFD'));setInvalidFieldCount((nextFields as typeof fields).length-safe.length);setFields(safe);const row=nextEmail as {inbound_address:string;sender_name:string;enabled:boolean};setEmail({inboundAddress:row.inbound_address,senderName:row.sender_name,enabled:row.enabled});}).catch(e=>setError(e.message));useEffect(()=>{void load();},[actor.organizationId]);const saveField=async(e:FormEvent)=>{e.preventDefault();try{await request('/admin/custom-fields',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({...field,options:field.fieldType==='SELECT'?field.options.split(',').map(v=>v.trim()).filter(Boolean):[]})});setField({fieldKey:'',label:'',fieldType:'TEXT',options:'',isRequired:false});onNotice('فیلد سفارشی ذخیره شد.');load();}catch(cause){setError(cause instanceof Error?cause.message:'خطا در ذخیره فیلد');}};const saveEmail=async(e:FormEvent)=>{e.preventDefault();try{await request('/admin/email-integration',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify(email)});onNotice('تنظیمات ایمیل ذخیره شد.');}catch(cause){setError(cause instanceof Error?cause.message:'خطا در ذخیره ایمیل');}};return <div className="admin-grid"><section className="card"><h3>فیلدهای سفارشی تیکت</h3><p className="hint">فقط فیلدهای فعال در فرم ثبت درخواست دیده می‌شوند.</p>{invalidFieldCount>0&&<p className="error" role="status">یک پیکربندی فیلد با عنوان خراب غیرفعال شده و در فرم تیکت نمایش داده نمی‌شود.</p>}<form onSubmit={saveField}><label>کلید انگلیسی<input dir="ltr" pattern="[a-z][a-z0-9_]{1,63}" value={field.fieldKey} onChange={e=>setField({...field,fieldKey:e.target.value})} required/></label><label>عنوان فارسی<input value={field.label} onChange={e=>setField({...field,label:e.target.value})} required/></label><label>نوع<select value={field.fieldType} onChange={e=>setField({...field,fieldType:e.target.value})}><option value="TEXT">متن</option><option value="NUMBER">عدد</option><option value="DATE">تاریخ</option><option value="SELECT">انتخابی</option><option value="BOOLEAN">بله/خیر</option></select></label>{field.fieldType==='SELECT'&&<label>گزینه‌ها (با ویرگول)<input value={field.options} onChange={e=>setField({...field,options:e.target.value})} required/></label>}<label className="checkbox-label"><input type="checkbox" checked={field.isRequired} onChange={e=>setField({...field,isRequired:e.target.checked})}/> الزامی</label><button>ذخیره فیلد</button></form><div className="list-compact">{fields.map(item=><p key={item.id}><strong>{item.label}</strong> <span dir="ltr">({item.field_key})</span> · {typeLabels[item.field_type]??'سفارشی'} {item.is_required?'· الزامی':''}</p>)}</div></section><section className="card"><h3>یکپارچه‌سازی ایمیل</h3><p className="hint">نشانی ورودی را در سرویس ایمیل سازمان به webhook ورودی Jupiter متصل کنید. رمز یا کلید سرویس در این فرم ذخیره نمی‌شود.</p><form onSubmit={saveEmail}><label>نشانی دریافت تیکت<input type="email" dir="ltr" value={email.inboundAddress} onChange={e=>setEmail({...email,inboundAddress:e.target.value})} required/></label><label>نام فرستنده<input value={email.senderName} onChange={e=>setEmail({...email,senderName:e.target.value})} required/></label><label className="checkbox-label"><input type="checkbox" checked={email.enabled} onChange={e=>setEmail({...email,enabled:e.target.checked})}/> فعال‌سازی دریافت ایمیل</label><button>ذخیره تنظیمات ایمیل</button></form></section>{error&&<p className="error" role="alert">{error}</p>}</div>; }

function CsvMemberImport({actor,onNotice}:{actor:Actor;onNotice:(message:string)=>void}) { const [rows,setRows]=useState<unknown[]>([]);const [preview,setPreview]=useState<{valid:boolean;rows:{row:number;email:string;displayName:string;roles:string[];errors:string[]}[]}|null>(null);const [error,setError]=useState('');const importKey=useRef('');const parseCsv=(text:string)=>{const output:string[][]=[];let row:string[]=[];let value='';let quoted=false;for(let index=0;index<text.length;index+=1){const char=text[index];if(char==='"'){if(quoted&&text[index+1]==='"'){value+='"';index+=1;}else quoted=!quoted;}else if(char===','&&!quoted){row.push(value.trim());value='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[index+1]==='\n')index+=1;row.push(value.trim());if(row.some(Boolean))output.push(row);row=[];value='';}else value+=char;}row.push(value.trim());if(row.some(Boolean))output.push(row);return output;};const parse=(file:File)=>{const reader=new FileReader();reader.onload=()=>{const [header,...body]=parseCsv(String(reader.result??'').replace(/^\uFEFF/,''));if(!header){setRows([]);setPreview(null);setError('فایل CSV خالی است.');return;}const columns=header.map(value=>value.trim());const parsed=body.map(values=>{const row=Object.fromEntries(columns.map((column,index)=>[column,values[index]??'']));return {...row,roles:String(row.roles??'REQUESTER').split('|').map(value=>value.trim()).filter(Boolean)};});importKey.current=crypto.randomUUID();setRows(parsed);setPreview(null);setError('');};reader.readAsText(file,'utf-8');};const check=async()=>{try{setPreview(await request('/admin/members/import/preview',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({rows})}) as typeof preview);}catch(cause){setError(cause instanceof Error?cause.message:'اعتبارسنجی فایل ناموفق بود.');}};const confirm=async()=>{try{const result=await request('/admin/members/import/confirm',actor.session,actor.organizationId,{method:'POST',headers:{'idempotency-key':importKey.current},body:JSON.stringify({rows})}) as {created:number;updated:number};onNotice(`${result.created} کاربر افزوده و ${result.updated} کاربر به‌روزرسانی شد.`);setRows([]);setPreview(null);importKey.current='';}catch(cause){setError(cause instanceof Error?cause.message:'ورود کاربران ناموفق بود.');}};return <section className="card csv-member-import"><h3>ورود گروهی CSV</h3><p className="hint">ستون‌ها: <span dir="ltr">email, displayName, username, password, roles</span>؛ نقش‌ها با <span dir="ltr">|</span> جدا می‌شوند. ابتدا پیش‌نمایش را بررسی کنید.</p><label className="file-input">انتخاب فایل CSV<input type="file" accept=".csv,text/csv" onChange={event=>{const file=event.target.files?.[0];if(file)parse(file);}}/></label>{rows.length>0&&<button type="button" className="secondary" onClick={()=>void check()}>بررسی {rows.length.toLocaleString('fa-IR')} ردیف</button>}{error&&<p className="error" role="alert">{error}</p>}{preview&&<><p className={preview.valid?'notice':'error'}>{preview.valid?'فایل آمادهٔ ورود است.':'خطاهای فایل را اصلاح کنید.'}</p><div className="table-wrap"><table><thead><tr><th>ردیف</th><th>ایمیل</th><th>نام</th><th>نتیجه</th></tr></thead><tbody>{preview.rows.map(row=><tr key={row.row}><td>{row.row}</td><td dir="ltr">{row.email}</td><td>{row.displayName}</td><td>{row.errors.join(' ')||'آماده'}</td></tr>)}</tbody></table></div>{preview.valid&&<button type="button" onClick={()=>void confirm()}>تأیید ورود گروهی</button>}</>}</section>; }

function DirectoryConnectorPanel({actor,onNotice}:{actor:Actor;onNotice:(message:string)=>void}) { const [connectors,setConnectors]=useState<{id:string;display_name:string;status:'UNPAIRED'|'PAIRED'|'REVOKED';paired_at:string|null;last_seen_at:string|null}[]>([]);const [displayName,setDisplayName]=useState('');const [pairing,setPairing]=useState<{connectorId:string;pairingCode:string;expiresAt:string}|null>(null);const [revokeTarget,setRevokeTarget]=useState<{id:string;display_name:string}|null>(null);const [error,setError]=useState('');const load=async()=>{try{setConnectors(await request('/directory/connectors',actor.session,actor.organizationId) as typeof connectors);}catch(cause){setError(cause instanceof Error?cause.message:'دریافت اتصال‌های دایرکتوری ناموفق بود.');}};useEffect(()=>{void load();},[actor.organizationId]);const create=async(event:FormEvent)=>{event.preventDefault();try{await request('/directory/connectors',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({displayName})});setDisplayName('');onNotice('اتصال دایرکتوری ایجاد شد؛ اکنون کد جفت‌سازی بسازید.');await load();}catch(cause){setError(cause instanceof Error?cause.message:'ساخت اتصال ناموفق بود.');}};const issue=async(id:string)=>{try{setPairing(await request(`/directory/connectors/${id}/pairings`,actor.session,actor.organizationId,{method:'POST'}) as typeof pairing);onNotice('کد جفت‌سازی فقط برای راه‌اندازی محلی نمایش داده می‌شود.');await load();}catch(cause){setError(cause instanceof Error?cause.message:'صدور کد جفت‌سازی ناموفق بود.');}};const revoke=async()=>{if(!revokeTarget)return;try{await request(`/directory/connectors/${revokeTarget.id}/revoke`,actor.session,actor.organizationId,{method:'POST'});setRevokeTarget(null);setPairing(null);onNotice('هویت دستگاه لغو شد و اتصال دیگر دسترسی ندارد.');await load();}catch(cause){setError(cause instanceof Error?cause.message:'لغو اتصال ناموفق بود.');}};const status=(value:string)=>value==='PAIRED'?'متصل':value==='REVOKED'?'لغوشده':'در انتظار جفت‌سازی';return <><section className="card"><div className="ui-section-header"><div><h3>اتصال Active Directory</h3><p className="hint">در این مرحله فقط اتصال و جفت‌سازی امن مدیریت می‌شود؛ همگام‌سازی کاربران در نسخهٔ بعد فعال می‌شود.</p></div><button type="button" className="secondary" onClick={()=>void load()}>تازه‌سازی</button></div><form onSubmit={create} className="inline-actions"><label>نام اتصال<input value={displayName} onChange={event=>setDisplayName(event.target.value)} placeholder="مثلاً دفتر مرکزی" maxLength={120} required/></label><button>ایجاد اتصال</button></form>{error&&<p className="error" role="alert">{error}</p>}<div className="table-wrap"><table><thead><tr><th>نام</th><th>وضعیت</th><th>آخرین اتصال</th><th>عملیات</th></tr></thead><tbody>{connectors.map(connector=><tr key={connector.id}><td>{connector.display_name}</td><td><span className={`status-pill ${connector.status==='PAIRED'?'active':'inactive'}`}>{status(connector.status)}</span></td><td>{connector.last_seen_at?new Date(connector.last_seen_at).toLocaleString('fa-IR'):'—'}</td><td className="table-actions">{connector.status!=='REVOKED'&&<button type="button" className="secondary" onClick={()=>void issue(connector.id)}>کد جفت‌سازی</button>}{connector.status!=='REVOKED'&&<button type="button" className="secondary" onClick={()=>setRevokeTarget(connector)}>لغو دستگاه</button>}</td></tr>)}{!connectors.length&&<tr><td colSpan={4}>اتصالی ثبت نشده است.</td></tr>}</tbody></table></div></section>{pairing&&<section className="card directory-pairing-code"><h3>کد جفت‌سازی موقت</h3><p className="hint">این کد را فقط در ابزار نصب‌شدهٔ سازمان وارد کنید. پس از جفت‌سازی یا پایان مهلت، دیگر قابل استفاده نیست.</p><code dir="ltr">{pairing.pairingCode}</code><p className="hint">اعتبار تا {new Date(pairing.expiresAt).toLocaleString('fa-IR')}</p><button type="button" className="secondary" onClick={()=>setPairing(null)}>بستن کد</button></section>}<ConfirmDialog open={Boolean(revokeTarget)} title="لغو هویت دستگاه" body={`دستگاه «${revokeTarget?.display_name??''}» فوراً دیگر اجازهٔ اتصال نخواهد داشت. برای اتصال دوباره، یک اتصال جدید بسازید.`} confirmLabel="لغو دستگاه" danger onConfirm={()=>void revoke()} onClose={()=>setRevokeTarget(null)}/></>; }

function MembersPanel({ actor, onNotice }: { actor: Actor; onNotice: (message: string) => void }) {
  const [members, setMembers] = useState<Member[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [form, setForm] = useState({ email: '', username: '', displayName: '', password: '', roles: ['REQUESTER'] as string[] });
  const load = () => { setLoading(true); request('/admin/members', actor.session, actor.organizationId).then(setMembers).catch((cause) => setError(cause.message)).finally(() => setLoading(false)); };
  useEffect(load, [actor.organizationId]);
  const submit = async (event: FormEvent) => { event.preventDefault(); try { await request('/admin/members', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify(form) }); setForm({ email: '', username:'', displayName: '', password: '', roles: ['REQUESTER'] }); onNotice('کاربر با موفقیت اضافه شد.'); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره کاربر ناموفق بود.'); } };
  return <div className="admin-stack"><section className="card"><div className="section-heading"><div><h3>اعضای سازمان</h3><p className="hint">نقش و وضعیت هر عضو در همین سازمان کنترل می‌شود.</p></div><button type="button" className="secondary" onClick={load}>تازه‌سازی</button></div>{error && <p className="error" role="alert">{error}</p>}{loading ? <p className="hint">در حال دریافت اعضا…</p> : <div className="table-wrap"><table><thead><tr><th>نام</th><th>ایمیل</th><th>نام کاربری</th><th>نقش‌ها</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{members.map((member) => <MemberRow key={member.id} actor={actor} member={member} onSaved={() => { onNotice('اطلاعات کاربر به‌روزرسانی شد.'); load(); }} />)}</tbody></table></div>}</section><section className="card"><h3>افزودن عضو</h3><form className="form-grid" autoComplete="off" onSubmit={submit}><label>نام نمایشی<input value={form.displayName} onChange={(event) => setForm({ ...form, displayName: event.target.value })} autoComplete="name" required /></label><label>ایمیل سازمانی<input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} autoComplete="off" required /></label><label>نام کاربری (اختیاری)<input dir="ltr" value={form.username} onChange={(event) => setForm({ ...form, username: event.target.value.toLowerCase() })} autoComplete="off" pattern="[a-z0-9][a-z0-9._-]{1,62}" /></label><label>رمز موقت<input type="password" minLength={10} value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} autoComplete="new-password" required /></label><RoleChecks value={form.roles} onChange={(next) => setForm({ ...form, roles: next })}/><button>افزودن کاربر</button></form></section></div>;
}

function MemberRow({ actor, member, onSaved }: { actor: Actor; member: Member; onSaved: () => void }) {
  const [editing, setEditing] = useState(false); const [displayName, setDisplayName] = useState(member.display_name); const [username, setUsername] = useState(member.username ?? ''); const [memberRoles, setMemberRoles] = useState(member.roles ?? []); const [status, setStatus] = useState(member.status); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const save = async () => { try { await request(`/admin/members/${member.id}`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ displayName, username:username||undefined, roles: memberRoles, status }) }); if (password) await request(`/admin/members/${member.id}/reset-password`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ password }) }); setPassword(''); setEditing(false); onSaved(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'به‌روزرسانی ناموفق بود.'); } };
  if (!editing) return <tr><td>{member.display_name}</td><td dir="ltr">{member.email}</td><td dir="ltr">{member.username ?? '—'}</td><td>{(member.roles ?? []).map((role) => roles.find(([code]) => code === role)?.[1] ?? role).join('، ')}</td><td><span className={`status-pill ${member.status}`}>{member.status === 'active' ? 'فعال' : 'غیرفعال'}</span></td><td><div className="member-actions"><button type="button" className="secondary" onClick={() => { setError(''); setEditing(true); }}>مدیریت</button></div></td></tr>;
  return <tr className="editing-row"><td colSpan={6}><div className="inline-editor"><label>نام<input value={displayName} onChange={(event) => setDisplayName(event.target.value)} autoComplete="name" /></label><label>نام کاربری<input dir="ltr" value={username} onChange={(event)=>setUsername(event.target.value.toLowerCase())} autoComplete="off" pattern="[a-z0-9][a-z0-9._-]{1,62}" /></label><label>وضعیت<select value={status} onChange={(event) => setStatus(event.target.value as 'active' | 'inactive')}><option value="active">فعال</option><option value="inactive">غیرفعال</option></select></label><label>رمز جدید (اختیاری)<input type="password" minLength={10} value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="new-password" /></label><RoleChecks value={memberRoles} onChange={setMemberRoles}/><p className="hint">با تعیین رمز جدید، نشست‌های فعال کاربر پس از ذخیره باطل می‌شوند.</p><div className="inline-actions"><button type="button" onClick={save} disabled={password.length > 0 && password.length < 10}>ذخیره</button><button type="button" className="secondary" onClick={() => { setPassword(''); setEditing(false); }}>انصراف</button></div></div>{error && <p className="error" role="alert">{error}</p>}</td></tr>;
}

function RoleChecks({ value, onChange }: { value: string[]; onChange: (roles: string[]) => void }) { return <fieldset className="role-checks"><legend>نقش‌ها</legend>{roles.map(([code, label]) => <label key={code}><input type="checkbox" checked={value.includes(code)} onChange={(event) => onChange(event.target.checked ? [...value, code] : value.filter((role) => role !== code))}/>{label}</label>)}</fieldset>; }

function CatalogPanel({ actor, onNotice }: { actor: Actor; onNotice: (message: string) => void }) {
  const [kind, setKind] = useState('departments'); const [items, setItems] = useState<CatalogItem[]>([]); const [code, setCode] = useState(''); const [name, setName] = useState(''); const [error, setError] = useState('');
  const [readiness,setReadiness]=useState<{categories:number;subcategories:number;departments:number;locations:number;disciplines:number;custom_fields:number;template_installed:boolean;aiReady:boolean}|null>(null);
  const [template,setTemplate]=useState<{name:string;installed:boolean;categories:{code:string;name:string;subcategories:{code:string;name:string}[]}[]}|null>(null);
  const [suggestions,setSuggestions]=useState<{id:string;kind:string;name:string;source:string;confidence:number|null}[]>([]);
  const load = () => Promise.all([request(`/admin/catalog/${kind}`, actor.session, actor.organizationId),request('/admin/catalog-readiness',actor.session,actor.organizationId),request('/admin/catalog-template',actor.session,actor.organizationId),request('/admin/catalog-suggestions',actor.session,actor.organizationId)]).then(([nextItems,nextReadiness,nextTemplate,nextSuggestions])=>{setItems(nextItems as CatalogItem[]);setReadiness(nextReadiness as typeof readiness);setTemplate(nextTemplate as typeof template);setSuggestions(nextSuggestions as typeof suggestions);}).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [kind, actor.organizationId]);
  const save = async (event: FormEvent) => { event.preventDefault(); try { await request(`/admin/catalog/${kind}`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ code, name }) }); setCode(''); setName(''); onNotice('آیتم کاتالوگ ذخیره شد.'); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره ناموفق بود.'); } };
  const install=async()=>{try{const result=await request('/admin/catalog-template/install',actor.session,actor.organizationId,{method:'POST'}) as {categoryCount:number;subcategoryCount:number};onNotice(`الگوی اولیه با ${result.categoryCount.toLocaleString('fa-IR')} دسته و ${result.subcategoryCount.toLocaleString('fa-IR')} زیردسته نصب شد.`);load();}catch(cause){setError(cause instanceof Error?cause.message:'نصب الگو ناموفق بود.');}};
  const review=async(id:string,decision:'APPROVED'|'REJECTED')=>{try{const code=decision==='APPROVED'?window.prompt('کد انگلیسی یکتا برای آیتم تأییدشده را وارد کنید:')?.trim():undefined;if(decision==='APPROVED'&&!code)return;await request(`/admin/catalog-suggestions/${id}/review`,actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({decision,code})});onNotice(decision==='APPROVED'?'پیشنهاد تأیید و وارد کاتالوگ شد.':'پیشنهاد رد شد.');load();}catch(cause){setError(cause instanceof Error?cause.message:'بازبینی پیشنهاد ناموفق بود.');}};
  return <div className="admin-stack"><section className="card"><h3>آمادگی کاتالوگ برای تکمیل هوشمند</h3>{readiness&&<><p className={readiness.aiReady?'notice':'hint'}>{readiness.aiReady?'دسته‌بندی و زیردسته برای پیشنهاد AI آماده‌اند.':'برای پیشنهاد دقیق AI، حداقل یک دسته و یک زیردسته تعریف کنید.'}</p><div className="list-compact"><p>دسته‌ها: {readiness.categories} · زیردسته‌ها: {readiness.subcategories} · واحدها: {readiness.departments} · مکان‌ها: {readiness.locations}</p></div></>}<h4>{template?.name??'الگوی خدمات IT و پشتیبانی سازمانی'}</h4><p className="hint">الگو فقط دسته‌ها و زیردسته‌های عمومی را نصب می‌کند؛ واحدها و مکان‌های اختصاصی سازمان را جداگانه وارد کنید.</p><button type="button" onClick={()=>void install()}>{template?.installed?'نصب یا به‌روزرسانی دوباره الگو':'نصب الگوی اولیه'}</button></section><div className="admin-grid"><section className="card"><h3>فهرست کاتالوگ</h3><label>نوع کاتالوگ<select value={kind} onChange={(event) => setKind(event.target.value)}>{catalogs.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>{error && <p className="error" role="alert">{error}</p>}<div className="table-wrap"><table><thead><tr><th>کد</th><th>نام</th></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td dir="ltr">{item.code}</td><td>{item.name}</td></tr>)}{!items.length && <tr><td colSpan={2}>هنوز آیتمی ثبت نشده است.</td></tr>}</tbody></table></div></section><section className="card"><h3>افزودن یا ویرایش با کد</h3><form onSubmit={save}><label>کد یکتا<input dir="ltr" value={code} onChange={(event) => setCode(event.target.value)} placeholder="IT-SUPPORT" required /></label><label>نام<input value={name} onChange={(event) => setName(event.target.value)} required /></label><button>ذخیره کاتالوگ</button></form></section></div><section className="card"><h3>پیشنهادهای در انتظار AI</h3><p className="hint">AI هیچ موردی را خودکار وارد کاتالوگ نمی‌کند. پیشنهادهای آینده در اینجا برای تأیید مدیر سازمان قرار می‌گیرند.</p>{suggestions.length?<div className="table-wrap"><table><thead><tr><th>نوع</th><th>نام</th><th>اطمینان</th><th>عملیات</th></tr></thead><tbody>{suggestions.map(item=><tr key={item.id}><td>{item.kind}</td><td>{item.name}</td><td>{item.confidence===null?'—':`${Math.round(item.confidence*100)}٪`}</td><td><button type="button" onClick={()=>void review(item.id,'APPROVED')}>تأیید</button><button type="button" className="secondary" onClick={()=>void review(item.id,'REJECTED')}>رد</button></td></tr>)}</tbody></table></div>:<p className="hint">پیشنهاد در انتظاری وجود ندارد.</p>}</section></div>;
}

function TeamsPanel({ actor, onNotice }: { actor: Actor; onNotice: (message: string) => void }) {
  const [teams, setTeams] = useState<Team[]>([]); const [members, setMembers] = useState<Member[]>([]); const [name, setName] = useState(''); const [memberIds, setMemberIds] = useState<string[]>([]); const [error, setError] = useState('');
  const load = () => Promise.all([request('/admin/teams', actor.session, actor.organizationId), request('/admin/members', actor.session, actor.organizationId)]).then(([nextTeams, nextMembers]) => { setTeams(nextTeams as Team[]); setMembers(nextMembers as Member[]); }).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [actor.organizationId]);
  const save = async (event: FormEvent) => { event.preventDefault(); try { await request('/admin/teams', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ name, memberIds, isActive: true }) }); setName(''); setMemberIds([]); onNotice('تیم ذخیره شد.'); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره تیم ناموفق بود.'); } };
  return <div className="admin-grid"><section className="card"><h3>تیم‌های فعال</h3>{teams.map((team) => <article className="list-item" key={team.id}><strong>{team.name}</strong><span className={`status-pill ${team.is_active ? 'active' : 'inactive'}`}>{team.is_active ? 'فعال' : 'غیرفعال'}</span><p className="hint">{team.members.map((member) => member.display_name).join('، ') || 'بدون عضو'}</p></article>)}{!teams.length && <p className="hint">هنوز تیمی تعریف نشده است.</p>}</section><section className="card"><h3>ساخت تیم</h3><form onSubmit={save}><label>نام تیم<input value={name} onChange={(event) => setName(event.target.value)} required /></label><fieldset className="member-picker"><legend>اعضای فعال</legend>{members.filter((member) => member.status === 'active').map((member) => <label key={member.user_id}><input type="checkbox" checked={memberIds.includes(member.user_id)} onChange={(event) => setMemberIds(event.target.checked ? [...memberIds, member.user_id] : memberIds.filter((id) => id !== member.user_id))}/>{member.display_name}</label>)}</fieldset><button>ذخیره تیم</button>{error && <p className="error" role="alert">{error}</p>}</form></section></div>;
}

function AutomationPanel({ actor, onNotice }: { actor: Actor; onNotice: (message: string) => void }) {
  const [rules, setRules] = useState<Rule[]>([]); const [departments, setDepartments] = useState<CatalogItem[]>([]); const [members, setMembers] = useState<Member[]>([]); const [departmentId, setDepartmentId] = useState(''); const [assigneeUserId, setAssigneeUserId] = useState(''); const [calendar, setCalendar] = useState({ timezone: 'Asia/Tehran', workdays: [1,2,3,4,5], startMinute: 480, endMinute: 1020 }); const [error, setError] = useState('');
  const load = () => Promise.all([request('/sla/rules', actor.session, actor.organizationId), request('/admin/catalog/departments', actor.session, actor.organizationId), request('/admin/members', actor.session, actor.organizationId), request('/sla/calendar', actor.session, actor.organizationId)]).then(([nextRules,nextDepartments,nextMembers,nextCalendar]) => { setRules(nextRules as Rule[]); setDepartments(nextDepartments as CatalogItem[]); setMembers(nextMembers as Member[]); const item=nextCalendar as {timezone:string;workdays:number[];start_minute:number;end_minute:number}; setCalendar({timezone:item.timezone,workdays:item.workdays,startMinute:item.start_minute,endMinute:item.end_minute}); }).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [actor.organizationId]);
  const saveRule = async (event: FormEvent) => { event.preventDefault(); try { await request('/sla/rules', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ departmentId: departmentId || undefined, assigneeUserId, isActive: true }) }); onNotice('قاعده تخصیص ذخیره شد.'); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره قاعده ناموفق بود.'); } };
  const saveCalendar = async (event: FormEvent) => { event.preventDefault(); try { await request('/sla/calendar', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify(calendar) }); onNotice('ساعات کاری ذخیره شد.'); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره ساعات ناموفق بود.'); } };
  const eligible = useMemo(() => members.filter((member) => member.status === 'active' && member.roles.some((role) => ['EXPERT','SUPERVISOR','ORG_ADMIN'].includes(role))), [members]);
  return <div className="admin-grid"><section className="card"><h3>قواعد تخصیص خودکار</h3><form onSubmit={saveRule}><label>واحد<select value={departmentId} onChange={(event) => setDepartmentId(event.target.value)}><option value="">همه واحدها</option>{departments.map((department) => <option key={department.id} value={department.id}>{department.name}</option>)}</select></label><label>مسئول<select value={assigneeUserId} onChange={(event) => setAssigneeUserId(event.target.value)} required><option value="">انتخاب کارشناس</option>{eligible.map((member) => <option key={member.user_id} value={member.user_id}>{member.display_name}</option>)}</select></label><button>ذخیره قاعده</button></form><div className="list-compact">{rules.map((rule) => <p key={rule.id}>واحد: {departments.find((department) => department.id === rule.department_id)?.name ?? 'همه واحدها'} ← {members.find((member) => member.user_id === rule.assignee_user_id)?.display_name ?? 'کاربر'}</p>)}</div></section><section className="card"><h3>تقویم کاری SLA</h3><form onSubmit={saveCalendar}><label>منطقه زمانی<input value={calendar.timezone} onChange={(event) => setCalendar({...calendar,timezone:event.target.value})}/></label><div className="time-fields"><label>شروع روز<input type="time" value={toTime(calendar.startMinute)} onChange={(event) => setCalendar({...calendar,startMinute:fromTime(event.target.value)})}/></label><label>پایان روز<input type="time" value={toTime(calendar.endMinute)} onChange={(event) => setCalendar({...calendar,endMinute:fromTime(event.target.value)})}/></label></div><fieldset className="weekday-picker"><legend>روزهای کاری</legend>{['دوشنبه','سه‌شنبه','چهارشنبه','پنج‌شنبه','جمعه','شنبه','یکشنبه'].map((label,index) => { const day=index+1; return <label key={day}><input type="checkbox" checked={calendar.workdays.includes(day)} onChange={(event) => setCalendar({...calendar,workdays:event.target.checked?[...calendar.workdays,day]:calendar.workdays.filter((item)=>item!==day)})}/>{label}</label>; })}</fieldset><button>ذخیره تقویم</button></form></section>{error && <p className="error" role="alert">{error}</p>}</div>;
}

function SettingsPanel({ actor, onNotice }: { actor: Actor; onNotice: (message: string) => void }) {
  const [settings, setSettings] = useState({ closurePolicy: 'STAFF_ONLY', reopenWindowDays: 7, businessTimezone: 'Asia/Tehran', smartIntakeEnabled: false, smartIntakeAvailable: false, smartIntakeReason: '' });
  const [templates, setTemplates] = useState<{id:string;name:string;body:string}[]>([]); const [template, setTemplate] = useState({ name: '', body: '' });
  const [logoUrl, setLogoUrl] = useState<string | null>(null); const [uploading, setUploading] = useState(false); const [error, setError] = useState('');
  const load = () => Promise.all([request('/admin/settings', actor.session, actor.organizationId), request('/admin/templates', actor.session, actor.organizationId), request('/admin/branding', actor.session, actor.organizationId)]).then(([nextSettings,nextTemplates,nextBranding]) => { const item=nextSettings as {closure_policy:string;reopen_window_days:number;business_timezone:string;smart_intake_enabled:boolean;smart_intake_available:boolean;smart_intake_reason:string|null}; setSettings({closurePolicy:item.closure_policy,reopenWindowDays:item.reopen_window_days,businessTimezone:item.business_timezone,smartIntakeEnabled:item.smart_intake_enabled,smartIntakeAvailable:item.smart_intake_available,smartIntakeReason:item.smart_intake_reason??''}); setTemplates(nextTemplates as {id:string;name:string;body:string}[]); setLogoUrl((nextBranding as {logo_url:string|null}).logo_url); }).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [actor.organizationId]);
  const saveSettings = async (event: FormEvent) => { event.preventDefault(); try { await request('/admin/settings', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify(settings) }); onNotice('تنظیمات سازمان ذخیره شد.'); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره ناموفق بود.'); } };
  const saveTemplate = async (event: FormEvent) => { event.preventDefault(); try { await request('/admin/templates', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify(template) }); setTemplate({name:'',body:''}); onNotice('قالب پاسخ ذخیره شد.'); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'ذخیره قالب ناموفق بود.'); } };
  const uploadLogo = async (event: ChangeEvent<HTMLInputElement>) => { const file=event.target.files?.[0]; if (!file) return; if (!['image/png','image/jpeg','image/webp'].includes(file.type) || file.size > 2 * 1024 * 1024) { setError('لوگو باید PNG، JPEG یا WebP و حداکثر ۲ مگابایت باشد.'); event.target.value=''; return; } setUploading(true); setError(''); try { const requested=await request('/admin/branding/upload-request',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({filename:file.name,contentType:file.type,byteSize:file.size})}) as {storageKey:string;uploadUrl:string}; const put=await fetch(requested.uploadUrl,{method:'PUT',headers:{'content-type':file.type},body:file}); if(!put.ok) throw new Error('بارگذاری لوگو ناموفق بود.'); const completed=await request('/admin/branding/complete',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({storageKey:requested.storageKey,contentType:file.type,byteSize:file.size})}) as {logo_url:string}; setLogoUrl(completed.logo_url); window.dispatchEvent(new CustomEvent('jupiter:brand-logo-updated',{detail:{logoUrl:completed.logo_url}})); onNotice('لوگوی سازمان با موفقیت به‌روزرسانی شد.'); } catch (cause) { setError(cause instanceof Error ? cause.message : 'بارگذاری لوگو ناموفق بود.'); } finally { setUploading(false); event.target.value=''; } };
  return <div className="admin-grid"><section className="card"><h3>سیاست بستن و بازگشایی</h3><form onSubmit={saveSettings}><label>سیاست بستن<select value={settings.closurePolicy} onChange={(event) => setSettings({...settings,closurePolicy:event.target.value})}><option value="STAFF_ONLY">فقط کارکنان</option><option value="REQUESTER_CONFIRMATION">تأیید درخواست‌کننده</option><option value="AUTO_EXPIRE">بستن خودکار</option></select></label><label>مهلت بازگشایی (روز)<input type="number" min="0" max="90" value={settings.reopenWindowDays} onChange={(event) => setSettings({...settings,reopenWindowDays:Number(event.target.value)})}/></label><label>منطقه زمانی کسب‌وکار<input value={settings.businessTimezone} onChange={(event) => setSettings({...settings,businessTimezone:event.target.value})}/></label><fieldset className="smart-intake-setting"><legend>تکمیل هوشمند درخواست‌ها</legend><label className="checkbox-label"><input type="checkbox" checked={settings.smartIntakeEnabled} disabled={!settings.smartIntakeAvailable} onChange={event=>setSettings({...settings,smartIntakeEnabled:event.target.checked})}/> ارسال هر پیام درخواست همراه با تحلیل AI انجام شود.</label>{settings.smartIntakeAvailable?<p className="hint">مدل تحلیل و کلید API توسط مدیر پلتفرم آماده است.</p>:<p className="hint">{settings.smartIntakeReason}</p>}</fieldset><button>ذخیره تنظیمات</button></form></section><section className="card brand-settings"><h3>هویت بصری و لوگو</h3><p className="hint">لوگو در نوار برنامه و منوی موبایل همین سازمان نمایش داده می‌شود.</p>{logoUrl && <img className="brand-logo-preview" src={logoUrl} alt="پیش‌نمایش لوگوی سازمان"/>}<label className="file-input">انتخاب و بارگذاری لوگو<input type="file" accept="image/png,image/jpeg,image/webp" onChange={uploadLogo} disabled={uploading}/></label>{uploading && <p className="hint" role="status">در حال بارگذاری امن لوگو…</p>}<ul className="upload-guidance"><li>فرمت مجاز: PNG، JPEG یا WebP (SVG پذیرفته نمی‌شود).</li><li>حداکثر حجم: ۲ مگابایت.</li><li>ابعاد پیشنهادی: مربع، حداقل ۵۱۲ × ۵۱۲ پیکسل؛ پس‌زمینه شفاف برای PNG/WebP بهتر است.</li></ul></section><section className="card"><h3>قالب‌های پاسخ</h3><form onSubmit={saveTemplate}><label>نام قالب<input value={template.name} onChange={(event) => setTemplate({...template,name:event.target.value})} required/></label><label>متن پاسخ<textarea value={template.body} onChange={(event) => setTemplate({...template,body:event.target.value})} required/></label><button>ذخیره قالب</button></form><div className="list-compact">{templates.map((item) => <article key={item.id}><strong>{item.name}</strong><p>{item.body}</p></article>)}</div></section>{error && <p className="error" role="alert">{error}</p>}</div>;
}

function toTime(minutes: number) { return `${String(Math.floor(minutes / 60)).padStart(2,'0')}:${String(minutes % 60).padStart(2,'0')}`; }
function fromTime(value: string) { const [hour, minute] = value.split(':').map(Number); return hour * 60 + minute; }

function DirectoryOperationalPanel({actor}:{actor:Actor}){const[connectors,setConnectors]=useState<any[]>([]),[scope,setScope]=useState<any>(null),[mappings,setMappings]=useState<any[]>([]),[message,setMessage]=useState('');const load=()=>Promise.all([request('/directory/connectors',actor.session,actor.organizationId),request('/directory/scope',actor.session,actor.organizationId),request('/directory/mappings',actor.session,actor.organizationId)]).then(([c,s,m])=>{setConnectors(c as any[]);setScope(s);setMappings(m as any[])}).catch(e=>setMessage(e instanceof Error?e.message:'دریافت عملیات Directory ناموفق بود.'));useEffect(()=>{void load()},[actor.organizationId]);const sync=(id:string)=>request(`/directory/connectors/${id}/sync-now`,actor.session,actor.organizationId,{method:'POST',headers:{'idempotency-key':crypto.randomUUID()}}).then(()=>setMessage('Sync در صف Connector قرار گرفت.')).catch(e=>setMessage(e instanceof Error?e.message:'ثبت Sync ناموفق بود.'));return <section className="card"><div className="ui-section-header"><div><h3>عملیات Directory</h3><p className="hint">Sync پانزده‌دقیقه‌ای «Snapshot افزایشی» است؛ حذف یا خروج از Scope فقط پس از Full Reconciliation کامل ارزیابی می‌شود.</p></div><button type="button" className="secondary" onClick={()=>void load()}>تازه‌سازی</button></div>{message&&<p className="hint" role="status">{message}</p>}<div className="table-wrap"><table><thead><tr><th>Connector</th><th>سلامت</th><th>نسخه</th><th>اجرای بعدی</th><th>عملیات</th></tr></thead><tbody>{connectors.map(c=>{const offline=['OFFLINE','NEVER_CONNECTED','DISABLED'].includes(c.operational_status);return <tr key={c.id}><td>{c.display_name}</td><td>{c.operational_status??c.status}</td><td dir="ltr">{c.version??'—'}</td><td>{offline?'در انتظار اتصال Connector':'طبق برنامه یا درخواست دستی'}</td><td><button type="button" className="secondary" disabled={offline} onClick={()=>void sync(c.id)}>Sync Now</button></td></tr>})}{!connectors.length&&<tr><td colSpan={5}>Connector عملیاتی وجود ندارد.</td></tr>}</tbody></table></div><p className="hint">Scope: {scope?.policy?.scope_type??'در حال دریافت'} · نسخه {scope?.policy?.version??'—'} · {scope?.catalog?.length??0} OU/Group کشف‌شده.</p><p className="hint">{mappings.length} نگاشت Group→Role ثبت شده است. نقش‌های مالک و مدیر سازمان هرگز از Directory تخصیص نمی‌گیرند.</p></section>}

function DirectoryConnectorControlPanel({actor,onNotice}:{actor:Actor;onNotice:(message:string)=>void}) {
  const [connectors,setConnectors]=useState<any[]>([]); const [displayName,setDisplayName]=useState(''); const [pairing,setPairing]=useState<any>(null); const [message,setMessage]=useState('');
  const load=()=>request('/directory/connectors',actor.session,actor.organizationId).then(value=>setConnectors(value as any[])).catch(cause=>setMessage(cause instanceof Error?cause.message:'دریافت Connector ناموفق بود.'));
  useEffect(()=>{void load();},[actor.organizationId]);
  const create=async(event:FormEvent)=>{event.preventDefault();try{await request('/directory/connectors',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({displayName})});setDisplayName('');onNotice('Connector ایجاد شد؛ اکنون کد جفت‌سازی بسازید.');await load();}catch(cause){setMessage(cause instanceof Error?cause.message:'ساخت Connector ناموفق بود.');}};
  const issue=async(id:string,rePair=false)=>{try{setPairing(await request(`/directory/connectors/${id}/${rePair?'re-pair':'pairings'}`,actor.session,actor.organizationId,{method:'POST'}));onNotice(rePair?'کد جفت‌سازی مجدد فقط برای دستگاه جایگزین نمایش داده می‌شود.':'کد جفت‌سازی فقط یک‌بار نمایش داده می‌شود.');await load();}catch(cause){setMessage(cause instanceof Error?cause.message:'صدور کد جفت‌سازی ناموفق بود.');}};
  const revoke=async(id:string)=>{try{await request(`/directory/connectors/${id}/revoke`,actor.session,actor.organizationId,{method:'POST'});onNotice('هویت دستگاه لغو شد.');await load();}catch(cause){setMessage(cause instanceof Error?cause.message:'لغو Connector ناموفق بود.');}};
  return <><section className="card"><div className="ui-section-header"><div><h3>Connector Active Directory</h3><p className="hint">سرویس Windows فقط با HTTPS خروجی متصل می‌شود؛ هیچ credential دایرکتوری به Jupiter ارسال یا ذخیره نمی‌شود.</p></div><button type="button" className="secondary" onClick={()=>void load()}>تازه‌سازی</button></div><form onSubmit={create} className="inline-actions"><label>نام Connector<input value={displayName} onChange={event=>setDisplayName(event.target.value)} maxLength={120} required/></label><button>ایجاد Connector</button></form>{message&&<p className="hint" role="status">{message}</p>}<div className="table-wrap"><table><thead><tr><th>نام</th><th>وضعیت</th><th>آخرین اتصال</th><th>عملیات</th></tr></thead><tbody>{connectors.map(connector=><tr key={connector.id}><td>{connector.display_name}</td><td>{connector.operational_status??connector.status}</td><td>{connector.last_seen_at?new Date(connector.last_seen_at).toLocaleString('fa-IR'):'—'}</td><td className="table-actions">{connector.status==='REVOKED'?<button type="button" className="secondary" onClick={()=>void issue(connector.id,true)}>جفت‌سازی مجدد</button>:<><button type="button" className="secondary" onClick={()=>void issue(connector.id)}>کد جفت‌سازی</button><button type="button" className="secondary" onClick={()=>void revoke(connector.id)}>لغو دستگاه</button></>}</td></tr>)}{!connectors.length&&<tr><td colSpan={4}>اتصالی ثبت نشده است.</td></tr>}</tbody></table></div></section>{pairing&&<section className="card directory-pairing-code"><h3>کد جفت‌سازی موقت</h3><p className="hint">کد فقط یک‌بار و تا {new Date(pairing.expiresAt).toLocaleString('fa-IR')} قابل استفاده است.</p><code dir="ltr">{pairing.pairingCode}</code><button type="button" className="secondary" onClick={()=>setPairing(null)}>بستن کد</button></section>}</>;
}

function DirectoryPolicyControls({actor}:{actor:Actor}) {
  const [data,setData]=useState<any>(null); const [scopeType,setScopeType]=useState('SELECTED_OUS'); const [selected,setSelected]=useState<string[]>([]); const [group,setGroup]=useState(''); const [role,setRole]=useState('REQUESTER'); const [message,setMessage]=useState('');
  const load=()=>Promise.all([request('/directory/scope',actor.session,actor.organizationId),request('/directory/mappings',actor.session,actor.organizationId)]).then(([scope,mappings])=>{const next=scope as any;setData({...next,mappings});setScopeType(next.policy.scope_type);setSelected(next.policy.scope_type==='SELECTED_GROUPS'?next.policy.selected_group_ids:next.policy.selected_ou_ids);}).catch(cause=>setMessage(cause instanceof Error?cause.message:'دریافت سیاست Directory ناموفق بود.'));
  useEffect(()=>{void load();},[actor.organizationId]);
  const catalog=(data?.catalog??[]).filter((item:any)=>scopeType==='SELECTED_GROUPS'?item.item_type==='GROUP':item.item_type==='OU').map((item:any)=>({...item,display_name:`${item.display_name} — کشف: ${item.last_discovered_at?new Date(item.last_discovered_at).toLocaleString('fa-IR'):'نامشخص'} · نسل ${item.generation??'—'}`}));
  const saveScope=async(event:FormEvent)=>{event.preventDefault();try{await request('/directory/scope',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({scopeType,selectedOuIds:scopeType==='SELECTED_OUS'?selected:[],selectedGroupIds:scopeType==='SELECTED_GROUPS'?selected:[]})});setMessage('سیاست Scope ذخیره شد و در Sync بعدی اعمال می‌شود.');await load();}catch(cause){setMessage(cause instanceof Error?cause.message:'ذخیره Scope ناموفق بود.');}};
  const saveMapping=async(event:FormEvent)=>{event.preventDefault();try{await request('/directory/mappings',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({groupExternalId:group,roleCode:role,enabled:true})});setMessage('نگاشت گروه ذخیره شد.');setGroup('');await load();}catch(cause){setMessage(cause instanceof Error?cause.message:'ذخیره نگاشت ناموفق بود.');}};
  return <div className="admin-grid"><section className="card"><h3>Scope رسمی Directory</h3><p className="hint">پیش‌فرض، OUهای انتخاب‌شده است. تغییر Scope حذف فوری ایجاد نمی‌کند؛ خروج از Scope هفت روز مهلت دارد.</p><form onSubmit={saveScope}><label>دامنه<select value={scopeType} onChange={event=>{setScopeType(event.target.value);setSelected([]);}}><option value="SELECTED_OUS">OUهای انتخاب‌شده</option><option value="SELECTED_GROUPS">گروه‌های انتخاب‌شده</option><option value="ENTIRE_DIRECTORY">کل Directory</option></select></label>{scopeType!=='ENTIRE_DIRECTORY'&&<fieldset className="member-picker"><legend>{scopeType==='SELECTED_OUS'?'OUهای کشف‌شده':'گروه‌های کشف‌شده'}</legend>{catalog.map((item:any)=><label key={item.external_id}><input type="checkbox" checked={selected.includes(item.external_id)} onChange={event=>setSelected(event.target.checked?[...selected,item.external_id]:selected.filter(id=>id!==item.external_id))}/>{item.display_name}</label>)}{!catalog.length&&<p className="hint">پس از heartbeat Connector، فهرست کشف‌شده اینجا نمایش داده می‌شود.</p>}</fieldset>}<button>ذخیره Scope</button></form></section><section className="card"><h3>نگاشت گروه به نقش</h3><p className="hint">فقط درخواست‌کننده، کارشناس و سرپرست قابل مدیریت هستند؛ نقش‌های مالک و مدیر سازمان همواره دستی باقی می‌مانند.</p><form onSubmit={saveMapping}><label>گروه<select value={group} onChange={event=>setGroup(event.target.value)} required><option value="">انتخاب گروه</option>{(data?.catalog??[]).filter((item:any)=>item.item_type==='GROUP').map((item:any)=><option key={item.external_id} value={item.external_id}>{item.display_name}</option>)}</select></label><label>نقش<select value={role} onChange={event=>setRole(event.target.value)}><option value="REQUESTER">درخواست‌کننده</option><option value="EXPERT">کارشناس</option><option value="SUPERVISOR">سرپرست</option></select></label><button>ذخیره نگاشت</button></form><div className="list-compact">{(data?.mappings??[]).map((item:any)=><p key={item.id}>{item.group_external_id} ← {item.role_code} · {item.enabled?'فعال':'غیرفعال'}</p>)}</div></section>{message&&<p className="hint" role="status">{message}</p>}</div>;
}

function DirectoryRunHistory({actor}:{actor:Actor}) {
  const [connectors,setConnectors]=useState<any[]>([]); const [runs,setRuns]=useState<any[]>([]); const [issues,setIssues]=useState<any[]>([]); const [selected,setSelected]=useState(''); const [message,setMessage]=useState('');
  const load=async(id=selected)=>{try{const list=await request('/directory/connectors',actor.session,actor.organizationId) as any[];setConnectors(list);const connectorId=id||list[0]?.id||'';setSelected(connectorId);if(connectorId){const [nextRuns,nextIssues]=await Promise.all([request(`/directory/connectors/${connectorId}/sync-runs`,actor.session,actor.organizationId),request('/directory/conflicts',actor.session,actor.organizationId,{headers:{'x-directory-connector-id':connectorId}})]);setRuns(nextRuns as any[]);setIssues(nextIssues as any[]);}}catch(cause){setMessage(cause instanceof Error?cause.message:'دریافت تاریخچه Directory ناموفق بود.');}};
  useEffect(()=>{void load();},[actor.organizationId]);
  return <section className="card"><div className="ui-section-header"><div><h3>تاریخچه و موارد نیازمند رسیدگی</h3><p className="hint">تنها Full Reconciliation کامل می‌تواند absence را به خروج از Scope یا تعلیق تبدیل کند.</p></div><button type="button" className="secondary" onClick={()=>void load()}>تازه‌سازی</button></div><label>Connector<select value={selected} onChange={event=>void load(event.target.value)}>{connectors.map(item=><option key={item.id} value={item.id}>{item.display_name}</option>)}</select></label>{message&&<p className="hint" role="status">{message}</p>}<div className="table-wrap"><table><thead><tr><th>زمان</th><th>نوع</th><th>وضعیت</th><th>کشف</th><th>ایجاد/به‌روزرسانی/تعلیق</th><th>Conflict</th></tr></thead><tbody>{runs.map(run=><tr key={run.id}><td>{new Date(run.created_at).toLocaleString('fa-IR')}</td><td>{run.sync_kind}</td><td>{run.status}</td><td>{run.discovered_count}</td><td>{run.create_count}/{run.update_count}/{run.suspend_count}</td><td>{run.conflict_count}</td></tr>)}{!runs.length&&<tr><td colSpan={6}>اجرایی ثبت نشده است.</td></tr>}</tbody></table></div>{issues.length>0&&<div className="list-compact"><h4>تعارض‌های باز</h4>{issues.map(item=><p key={item.id}>{item.conflict_type} · دادهٔ AD یا Jupiter را اصلاح کنید و سپس Sync را دوباره اجرا کنید.</p>)}</div>}</section>;
}
